import functools


def memo(fn):
    """Cache results by arguments."""
    cache = {}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        if args not in cache:
            cache[args] = fn(*args, **kwargs)
        return cache[args]

    return wrapper

