def process_orders(orders, stock, vip_customers):
    """Returns (shipped, rejected, report_lines) and updates stock in place."""
    shipped = []
    rejected = []
    lines = []
    for order in orders:
        if not order.get("items"):
            rejected.append((order["id"], "empty order"))
            lines.append(f"{order['id']}: rejected (empty order)")
            continue
        ok = True
        for name, qty in order["items"].items():
            if qty <= 0:
                ok = False
                reason = f"bad quantity for {name}"
                break
            if stock.get(name, 0) < qty:
                ok = False
                reason = f"not enough {name}"
                break
        if not ok:
            rejected.append((order["id"], reason))
            lines.append(f"{order['id']}: rejected ({reason})")
            continue
        total = 0
        for name, qty in order["items"].items():
            price = order["prices"][name]
            total += price * qty
            stock[name] -= qty
        if order["customer"] in vip_customers:
            discount = 0.1
        elif total >= 100:
            discount = 0.05
        else:
            discount = 0
        total = round(total * (1 - discount), 2)
        if total >= 50 or order["customer"] in vip_customers:
            shipping = 0
        else:
            shipping = 4.99
        grand = round(total + shipping, 2)
        shipped.append({"id": order["id"], "total": total, "shipping": shipping, "grand": grand})
        if discount:
            lines.append(f"{order['id']}: shipped {grand:.2f} ({int(discount * 100)}% off)")
        else:
            lines.append(f"{order['id']}: shipped {grand:.2f}")
    lines.append(f"{len(shipped)} shipped, {len(rejected)} rejected")
    return shipped, rejected, lines

